insert into menu_items (id, venue, category, name, description, price, sort, badge, photo_path) values
('khleb-hookah-classic', 'khleb', 'hookah', 'Классика', 'Знакомая всем чаша', 2200, 1, null, 'img/hookah/hookah-classic.jpg'),
('khleb-hookah-cigar', 'khleb', 'hookah', 'Сигарная чаша', 'Чаша с использованием блендов сигарного листа', 2400, 2, null, 'img/hookah/hookah-cigar-bowl.jpg'),
('khleb-hookah-grapefruit', 'khleb', 'hookah', 'Грейпфрут', 'Легендарное авторское исполнение чаши на грейпфруте от амбассадоров заведения. Непревзойдённое качество и длительность сеанса курения от 2-х часов', 2950, 3, 'Хит', 'img/hookah/hookah-grapefruit.jpg'),
('khleb-hookah-milk', 'khleb', 'hookah', 'Кальян на молоке', 'Использование молока в колбе придает бархатистую сливочную нотку, дополняя и раскрывая вкусовую палитру', 350, 4, null, 'img/hookah/hookah-milk.jpg'),
('khleb-hookah-ice', 'khleb', 'hookah', 'Ледяная колба', 'Добавление льда в колбу', 350, 5, null, 'img/hookah/hookah-ice.jpg'),
('khleb-pizza-pepperoni', 'khleb', 'pizza', 'Дабл Пепперони', 'Любимая пепперони с бооооольшим количеством аппетитных колбасок! Томатная основа, горячая моцарелла и много-много сочной пепперони!', 890, 1, 'Хит', 'barkas_files/pizza-pepperoni.jpg'),
('khleb-pizza-bbq', 'khleb', 'pizza', 'Бекон Барбекю', 'Ярко, сочно! Томатная основа, горячая моцарелла, аппетитный бекон, слайсы шампиньонов, красный лук и мнооого фирменного соуса барбекю.', 870, 2, null, 'barkas_files/pizza-bbq.jpg'),
('khleb-pizza-salsa', 'khleb', 'pizza', 'Супермясная Сальса', 'Как же много начинки! Томатная основа, горячая моцарелла, много пепперони, слайсы бекона, ветчина из индейки, стручковая фасоль, кукуруза и еще сооооус сальса. Объедение!', 890, 3, null, 'barkas_files/pizza-salsa.jpg'),
('khleb-pizza-pesto', 'khleb', 'pizza', 'Маргарита Песто', 'Простая, но не скучная классика! Томатная основа, горячая тянущаяся моцарелла и оригинальный соус песто.', 850, 4, null, 'barkas_files/pizza-pesto.jpg'),
('khleb-pizza-bechamel', 'khleb', 'pizza', 'Цыпленок Бешамель', 'Когда хочется курочки! Авторский соус бешамель в основе, тянущаяся моцарелла, подкопченный цыпленок, слайсы шампиньонов, болгарский перец, кукуруза.', 870, 5, null, 'barkas_files/pizza-bechamel.jpg'),
('khleb-tea-author', 'khleb', 'tea', 'Авторский чай', 'Расскажите, какое у вас настроение, — и мы соберём чай именно под него: согревающий, бодрящий или медитативный. 750 ₽, не входит в депозит.', 750, 1, null, null),
('khleb-tea-season', 'khleb', 'tea', 'Сезонный чай', 'Собран так, чтобы поддержать вас даже в самую плохую погоду. Состав сезона уточняйте у администратора.', null, 2, null, null),
('khleb-tea-china', 'khleb', 'tea', 'Китайский чай', 'Шу пуэр, молочный улун, манговый улун, тайваньский улун, да хун пао', 400, 3, null, null),
('khleb-tea-black', 'khleb', 'tea', 'Чёрный чай', 'Свежие ягоды, ройбуш, индийский чёрный', 400, 4, null, null),
('khleb-tea-fruit', 'khleb', 'tea', 'Фруктовый чай', 'Вишневый рай, малиновый коктейль, мужская энергия, зеленый с жасмином', 400, 5, null, null),
('khleb-coffee-espresso', 'khleb', 'coffee', 'Двойной эспрессо', '', null, 1, null, null),
('khleb-coffee-americano', 'khleb', 'coffee', 'Американо', '', null, 2, null, null),
